//! One descriptor transferred by trusted pre-exec code, before payload execution.
use std::io;
use std::os::fd::{FromRawFd, OwnedFd, RawFd};

pub(super) fn send(socket: RawFd, descriptor: RawFd) -> io::Result<()> {
    let mut byte = 1u8;
    let mut iov = libc::iovec {
        iov_base: (&mut byte as *mut u8).cast(),
        iov_len: 1,
    };
    let mut control = [0usize; 4];
    // SAFETY: aligned, initialized backing memory outlives the syscall; all
    // headers and lengths are generated by libc's ancillary-data ABI helpers.
    unsafe {
        let mut message: libc::msghdr = std::mem::zeroed();
        message.msg_iov = &mut iov;
        message.msg_iovlen = 1;
        message.msg_control = control.as_mut_ptr().cast();
        message.msg_controllen = libc::CMSG_SPACE(std::mem::size_of::<i32>() as u32) as usize;
        let header = libc::CMSG_FIRSTHDR(&message);
        (*header).cmsg_level = libc::SOL_SOCKET;
        (*header).cmsg_type = libc::SCM_RIGHTS;
        (*header).cmsg_len = libc::CMSG_LEN(std::mem::size_of::<i32>() as u32) as usize;
        libc::CMSG_DATA(header).cast::<i32>().write(descriptor);
        if libc::sendmsg(socket, &message, libc::MSG_NOSIGNAL) != 1 {
            return Err(io::Error::last_os_error());
        }
    }
    Ok(())
}

pub(super) fn receive(socket: RawFd) -> io::Result<OwnedFd> {
    let mut byte = 0u8;
    let mut iov = libc::iovec {
        iov_base: (&mut byte as *mut u8).cast(),
        iov_len: 1,
    };
    let mut control = [0usize; 4];
    let mut descriptors = Vec::new();
    // SAFETY: recvmsg populates bounded aligned storage; SCM_RIGHTS descriptors
    // transfer ownership. Wrap all of them before validation so errors cannot leak.
    let valid = unsafe {
        let mut message: libc::msghdr = std::mem::zeroed();
        message.msg_iov = &mut iov;
        message.msg_iovlen = 1;
        message.msg_control = control.as_mut_ptr().cast();
        message.msg_controllen = std::mem::size_of_val(&control);
        let count = libc::recvmsg(
            socket,
            &mut message,
            libc::MSG_DONTWAIT | libc::MSG_CMSG_CLOEXEC,
        );
        if count < 0 {
            return Err(io::Error::last_os_error());
        }
        let mut header = libc::CMSG_FIRSTHDR(&message);
        while !header.is_null() {
            if (*header).cmsg_level == libc::SOL_SOCKET && (*header).cmsg_type == libc::SCM_RIGHTS {
                let length = (*header)
                    .cmsg_len
                    .saturating_sub(libc::CMSG_LEN(0) as usize)
                    / 4;
                for i in 0..length {
                    descriptors.push(OwnedFd::from_raw_fd(
                        libc::CMSG_DATA(header).cast::<i32>().add(i).read(),
                    ));
                }
            }
            header = libc::CMSG_NXTHDR(&message, header);
        }
        count == 1 && byte == 1 && message.msg_flags & (libc::MSG_CTRUNC | libc::MSG_TRUNC) == 0
    };
    if !valid || descriptors.len() != 1 {
        return Err(io::Error::other("invalid sandbox listener transfer"));
    }
    Ok(descriptors.remove(0))
}
